const secret = $json.headers?.['x-webhook-secret'] || $json.headers?.['X-Webhook-Secret'];
if ($env.N8N_WEBHOOK_SECRET && secret !== $env.N8N_WEBHOOK_SECRET) throw new Error('Invalid webhook secret');
const body = $json.body || $json;
if (!body.listingId || !body.title || !body.description) throw new Error('Invalid listing payload');
return [{ json: body }];

const original = $('Validate payload').first().json;
const result = JSON.parse($json.choices[0].message.content);
return [{ json: { ...original, ...result, embeddingText: `Title: ${result.cleaned_title || original.title}. Category: ${original.categoryId}. Description: ${result.cleaned_description || original.description}. Price: ${original.price} ${original.currency}. Location: ${original.locationId}` } }];

const listing = $('Normalize AI result').first().json;
const vector = $json.data[0].embedding;
return [{ json: { ...listing, vector } }];
